        return Stream.of(FormatInfo.READ_WRITE_FORMATS);
    }

@ParameterizedTest
    @MethodSource("data")
    public void testNullParametersRoundtrip(final FormatInfo formatInfo) throws Exception {
        final BufferedImage testImage = TestImages.createFullColorImage(1, 1);
        final File temp1 = File.createTempFile("nullParameters.", "." + formatInfo.format.getDefaultExtension());
        Imaging.writeImage(testImage, temp1, formatInfo.format);
        Imaging.getImageInfo(temp1);
        Imaging.getImageSize(temp1);
        Imaging.getMetadata(temp1);
        Imaging.getICCProfile(temp1);
        final BufferedImage imageRead = Imaging.getBufferedImage(temp1);

        assertNotNull(imageRead);
    }

protected void roundtrip(final FormatInfo formatInfo, final BufferedImage testImage,
                             final String tempPrefix, final boolean imageExact) throws IOException,
            ImageReadException, ImageWriteException {
        final File temp1 = File.createTempFile(tempPrefix + ".", "."
                + formatInfo.format.getDefaultExtension());
        Debug.debug("tempFile: " + temp1.getName());

        ImageParser imageParser = Util.getImageParser(formatInfo.format);

        final ImagingParameters params = Util.getImageParser(formatInfo.format).getDefaultParameters();
        try (FileOutputStream fos = new FileOutputStream(temp1)) {
            imageParser.writeImage(testImage, fos, params);
        }

        final ImagingParameters readParams = Util.getImageParser(formatInfo.format).getDefaultParameters();
        readParams.setBufferedImageFactory(new RgbBufferedImageFactory());
        final BufferedImage image2 = imageParser.getBufferedImage(temp1, readParams);
        assertNotNull(image2);

        if (imageExact) {
            // note tolerance when comparing grayscale images
            // BufferedImages of
            ImageAsserts.assertEquals(testImage, image2);
        }

        if (formatInfo.identicalSecondWrite) {
            final File temp2 = File.createTempFile(tempPrefix + ".", "." + formatInfo.format.getDefaultExtension());
            try (FileOutputStream fos = new FileOutputStream(temp2)) {
                imageParser.writeImage(image2, fos, params);
            }

            ImageAsserts.assertEquals(temp1, temp2);
        }
    }

public static Stream<Arguments> createRoundtripArguments(final BufferedImage[] images) {
        return Stream.of(images).flatMap(i -> Stream.of(FormatInfo.READ_WRITE_FORMATS).map(f -> Arguments.of(i, f)));
    }

public static Stream<FormatInfo> testPixelDensityRoundtrip() {
        return Stream.of(FormatInfo.PRESERVING_RESOLUTION_FORMATS);
    }

@ParameterizedTest
    @MethodSource
    public void testPixelDensityRoundtrip(final FormatInfo formatInfo) throws Exception {
        final BufferedImage testImage = TestImages.createFullColorImage(2, 2);

        final File temp1 = File.createTempFile("pixeldensity.", "." + formatInfo.format.getDefaultExtension());

        final TiffImagingParameters params = new TiffImagingParameters();
        final PixelDensity pixelDensity = PixelDensity.createFromPixelsPerInch(75, 150);
        params.setPixelDensity(pixelDensity);
        TiffImageParser tiffImageParser = new TiffImageParser();
        tiffImageParser.writeImage(testImage, new ByteArrayOutputStream(), params);

        final ImageInfo imageInfo = Imaging.getImageInfo(temp1);
        if (imageInfo != null) {
            final int xReadDPI = imageInfo.getPhysicalWidthDpi();
            final int yReadDPI = imageInfo.getPhysicalHeightDpi();
            // allow a 5% margin of error in storage and conversion
            assertTrue(Math.abs((xReadDPI - pixelDensity.horizontalDensityInches())/ pixelDensity.horizontalDensityInches())<= 0.05);
            assertTrue(Math.abs((yReadDPI - pixelDensity.verticalDensityInches())/ pixelDensity.verticalDensityInches())<= 0.05);
        }
    }

@Test
    public void testFloatToByteConversion() {
        final byte[] bytesLE = ByteConversions.toBytes(1.0f, ByteOrder.LITTLE_ENDIAN);
        assertEquals(ByteConversions.toFloat(bytesLE, ByteOrder.LITTLE_ENDIAN), 1.0f, 0f);

        final byte[] bytesBE = ByteConversions.toBytes(1.0f, ByteOrder.BIG_ENDIAN);
        assertEquals(ByteConversions.toFloat(bytesBE, ByteOrder.BIG_ENDIAN), 1.0f, 0f);
    }

@Test
    public void testDoubleToByteConversion() {
        final byte[] bytesLE = ByteConversions.toBytes(1.0, ByteOrder.LITTLE_ENDIAN);
        assertEquals(ByteConversions.toDouble(bytesLE, ByteOrder.LITTLE_ENDIAN), 1.0, 0);

        final byte[] bytesBE = ByteConversions.toBytes(1.0, ByteOrder.BIG_ENDIAN);
        assertEquals(ByteConversions.toDouble(bytesBE, ByteOrder.BIG_ENDIAN), 1.0, 0);
    }

