@Test
  public void testApplyFloydSteinbergDitheringWithNonNullOne() throws ImageWriteException {
      final BufferedImage bufferedImage = new BufferedImage(8, 8, 8);
      bufferedImage.setRGB(2, 2, 2);
      final List<ColorSpaceSubset> linkedList = new LinkedList<>();
      final ColorSpaceSubset colorSpaceSubset = new ColorSpaceSubset((-234), (-352));
      colorSpaceSubset.rgb = 8;
      linkedList.add(colorSpaceSubset);
      final QuantizedPalette quantizedPalette = new QuantizedPalette(linkedList, 8);
      Dithering.applyFloydSteinbergDithering(bufferedImage, quantizedPalette);

      assertEquals(-16777208, bufferedImage.getRGB(0,0) );
      assertEquals(-16777208, bufferedImage.getRGB(1,1) );
      assertEquals(-16777208, bufferedImage.getRGB(2,1) );
      assertEquals(-16777208, bufferedImage.getRGB(2,2) );
  }

@Test
  public void testApplyFloydSteinbergDitheringWithNonNullTwo() throws ImageWriteException {
      final BufferedImage bufferedImage = new BufferedImage(3, 3, 3);
      bufferedImage.setRGB(1, 2, 4);
      final List<ColorSpaceSubset> linkedList = new LinkedList<>();
      final ColorSpaceSubset colorSpaceSubset = new ColorSpaceSubset((-234), (-352));
      linkedList.add(colorSpaceSubset);
      final QuantizedPalette quantizedPalette = new QuantizedPalette(linkedList, 3);
      Dithering.applyFloydSteinbergDithering(bufferedImage, quantizedPalette);

      assertEquals(-1, bufferedImage.getRGB(0,0) );
      assertEquals(-1, bufferedImage.getRGB(1,1) );
      assertEquals(-1, bufferedImage.getRGB(2,1) );
      assertEquals(-1, bufferedImage.getRGB(2,2) );
  }

public static void main(final String[] args) throws ImageReadException, IOException {
        if (args.length == 0) {
            // Print usage and exit
            for (final String s : USAGE) {
                System.err.println(s);
            }
            System.exit(0);
        }

        final File target = new File(args[0]);
        String outputPath = null;
        if (args.length == 2) {
            outputPath = args[1];
        }
        final boolean optionalImageWritingEnabled
            = outputPath != null && !outputPath.isEmpty();

        final ByteSourceFile byteSource = new ByteSourceFile(target);

        // Establish a TiffReader. This is just a simple constructor that
        // does not actually access the file.  So the application cannot
        // obtain the byteOrder, or other details, until the contents has
        // been read.  Then read the directories associated with the
        // file by passing in the byte source and options.
        final TiffReader tiffReader = new TiffReader(true);

        // Read the directories in the TIFF file.  Directories are the
        // main data element of a TIFF file. They usually include an image
        // element, but sometimes just carry metadata. This example
        // reads all the directories in the file, but if we were interested
        // in just the first element, Commons Imaging provides alternate API's
        // that would be more efficient.
        final TiffContents contents = tiffReader.readDirectories(
            byteSource,
            true, // indicates that application should read image data, if present
            FormatCompliance.getDefault());


        // Render the first directory in the file.  A practical implementation
        // could use any of the directories in the file. This demo uses the
        // first one just for simplicity.
        final TiffDirectory directory = contents.directories.get(0);
        // Render the first directory in the file
        if (!directory.hasTiffImageData()) {
            System.err.println("First directory in file does not have image");
            System.exit(-1);
        }

        // Obtain metadata about what kind of data is in the product.
        // Because this demo is designed for floating-point data,
        // it will expect the sample format to include only one element
        // of type floating point.   Beyond that, the TIFF specification
        // allows a large number of variations in format (16, 24, or 32 byte
        // floats; tiles versus strips; etc.).  Unfortunately the test data
        // for the less common variations was not available when Commons Imaging
        // was implemented and so the API will not be able to handle all
        // of them.  This test will simply allow the API to throw an exception
        // if an unsupported format is encountered.
        //    The getFieldValue call allows an application to provide a
        // boolean indicating that the field must be present for processing
        // to continue. If it does not, an exception is thrown.
        final short[] sampleFormat = directory.getFieldValue(TiffTagConstants.TIFF_TAG_SAMPLE_FORMAT, true);
        final short samplesPerPixel = directory.getFieldValue(TiffTagConstants.TIFF_TAG_SAMPLES_PER_PIXEL);
        final short[] bitsPerPixel = directory.getFieldValue(TiffTagConstants.TIFF_TAG_BITS_PER_SAMPLE, true);
        if (sampleFormat[0] != TiffTagConstants.SAMPLE_FORMAT_VALUE_IEEE_FLOATING_POINT) {
            System.err.println("This example requires a data source with a floating-point format");
            System.exit(-1);
        }

        System.out.print("Bits per pixel: ");
        for (int i = 0; i < samplesPerPixel; i++) {
            System.out.format("%s%d", i > 0 ? ", " : "", bitsPerPixel[i]);
        }
        System.out.println("");

        // Create a TIFF Photometric Interpreter to perform a grayscale
        // rendering.  A Photometric Interpreter is a class that maps a
        // floating-point value to a pixel (RGB) equivalent.
        // Because there is no way to know the range of
        // values in the TIFF before it is read.  So the special-purpose
        // interpreter permits an application to extract the
        // min and maximum bounds of the data as an auxiliary function
        // of interpreting the data. Unfortunately, if we wish for a
        // good interpretation, we need to read the data twice.
        //    For this demo, we store the Photometric Interpreter instance
        // as a option-parameter to be passed into the read-image method.
        final PhotometricInterpreterFloat pi = new PhotometricInterpreterFloat(0.0f, 1.0f);
        TiffImagingParameters params = new TiffImagingParameters();
        params.setCustomPhotometricInterpreter(pi);
        BufferedImage bImage = directory.getTiffImage(params);

        final float maxValue = pi.getMaxFound();
        final float minValue = pi.getMinFound();

        // System.out.format("Image size %dx%d%n", bImage.getWidth(), bImage.getHeight());
        // System.out.format("Range of values in TIFF: %f %f%n", minValue, maxValue);

        if (optionalImageWritingEnabled) {
            final File output = new File(outputPath);
            // create a new photometric interpreter based on the range
            // of values found above.
            final PhotometricInterpreterFloat grayScale
                = new PhotometricInterpreterFloat(minValue, maxValue);
            params = new TiffImagingParameters();
            params.setCustomPhotometricInterpreter(grayScale);
            bImage = directory.getTiffImage(params);
            ImageIO.write(bImage, "JPEG", output);
        }
    }

public static void main(final String[] args)
        throws ImageReadException, IOException {
        if (args.length == 0) {
            // Print usage and exit
            for (final String s : USAGE) {
                System.err.println(s);
            }
            System.exit(0);
        }

        // For brevity, map System.out to a PrintStream reference.
        // In the future, this might also be used for writing to a text file
        // rather than standard output.
        PrintStream ps = System.out;

        final File target = new File(args[0]);
        String rootName = null;
        if (args.length == 2) {
            rootName = args[1];
        }
        final boolean optionalImageReadingEnabled
            = rootName != null && !rootName.isEmpty();

        final ByteSourceFile byteSource = new ByteSourceFile(target);
        final TiffImagingParameters params = new TiffImagingParameters();

        // Establish a TiffReader. This is just a simple constructor that
        // does not actually access the file.  So the application cannot
        // obtain the byteOrder, or other details, until the contents has
        // been read.  Then read the directories associated with the
        // file by passing in the byte source and options.
        final TiffReader tiffReader = new TiffReader(true);
        final TiffContents contents = tiffReader.readDirectories(
            byteSource,
            optionalImageReadingEnabled, // read image data, if present
            FormatCompliance.getDefault());

        // Loop on the directories and fetch the metadata and
        // image (if available, and configured to do so)
        int iDirectory = 0;
        for (final TiffDirectory directory : contents.directories) {
            // Get the metadata (Tags) and write them to standard output
            final boolean hasTiffImageData = directory.hasTiffImageData();
            if (iDirectory > 0) {
                ps.println("\n-----------------------------------------------------\n");
            }

            String contentType = "";
            if (directory.hasTiffRasterData()) {
                contentType = "Numeric raster data";
            } else if (directory.hasTiffImageData()) {
                contentType = "Image data";
            }
            ps.format("Directory %2d %s, description: %s%n",
                iDirectory,
                contentType,
                directory.description());
            // Loop on the fields, printing the metadata (fields) ----------
            final List<TiffField> fieldList = directory.getDirectoryEntries();
            for (final TiffField tiffField : fieldList) {
                String s = tiffField.toString();
                if (s.length() > 90) {
                    s = s.substring(0, 90);
                }
                // In the case if the offsets (file positions) for the Strips
                // or Tiles, the string may be way too long for output and
                // will be truncated.  Therefore, indicate the numnber of entries.
                // These fields are indicated by numerical tags 0x144 and 0x145
                if (tiffField.getTag() == 0x144 || tiffField.getTag() == 0x145) {
                    final int i = s.indexOf(')');
                    final int[] a = tiffField.getIntArrayValue();
                    s = s.substring(0, i + 2) + " [" + a.length + " entries]";
                }
                ps.println(" " + s);
            }

            summarizeGeoTiffTags(ps, directory);

            if (optionalImageReadingEnabled && hasTiffImageData) {
                final File output = new File(rootName + "_" + iDirectory + ".jpg");
                ps.println("Writing image to " + output.getPath());
                final BufferedImage bImage = directory.getTiffImage(params);
                ImageIO.write(bImage, "JPEG", output);
            }
            ps.println("");
            iDirectory++;
        }
    }

private static void summarizeGeoTiffTags(PrintStream ps, TiffDirectory directory)
        throws ImageReadException {

        if (keyMap == null) {
            GeoKey[] values = GeoKey.values();
            int maxNameLength = 0;
            keyMap = new HashMap<>();
            for (GeoKey g : values) {
                String name = g.name();
                if (name.length() > maxNameLength) {
                    maxNameLength = name.length();
                }
                keyMap.put(g.key, g);
            }
            // create a formatting string that will pad all names
            // out with trailing spaces to provide text alignment in code below.
            nameFormat = String.format("   %%-%ds", maxNameLength);
        }

        // check to see if the directory has GeoTIFF tags.
        short[] geoKeyDirectory = directory.getFieldValue(
            GeoTiffTagConstants.EXIF_TAG_GEO_KEY_DIRECTORY_TAG, false);
        if (geoKeyDirectory == null || geoKeyDirectory.length < 4) {
            // The TIFF directory does not contain GeoTIFF information
            return;
        }
        ps.println("");
        ps.println("Summary of GeoTIFF Elements ----------------------------");

        short[] bitsPerSample = directory.getFieldValue(
            TiffTagConstants.TIFF_TAG_BITS_PER_SAMPLE, false);
        short[] sampleFormat = directory.getFieldValue(
            TiffTagConstants.TIFF_TAG_SAMPLE_FORMAT, false);
        String contentTypeString = null;
        if (bitsPerSample != null && sampleFormat != null) {
            if (bitsPerSample[0] == 16 && sampleFormat[0] == TiffTagConstants.SAMPLE_FORMAT_VALUE_TWOS_COMPLEMENT_SIGNED_INTEGER) {
                contentTypeString = "Numeric, Short Integer";
            } else if ((bitsPerSample[0] == 32 || bitsPerSample[0] == 64)
                && sampleFormat[0] == TiffTagConstants.SAMPLE_FORMAT_VALUE_IEEE_FLOATING_POINT) {
                contentTypeString = "Numeric, Floating Point (" + bitsPerSample[0] + "-bit samples)";
            }
        }
        if (contentTypeString != null) {
            ps.format("%nContent Type: %s", contentTypeString);
            String gdalNoDataString[] = directory.getFieldValue(
                GdalLibraryTagConstants.EXIF_TAG_GDAL_NO_DATA, false);
            if (gdalNoDataString != null && gdalNoDataString.length > 0) {
                ps.format("    GDAL No-Data value: %s", gdalNoDataString[0]);
            }
            ps.format("%n");
        }

        // all GeoKeyDirectory elements are unsigned shorts (2 bytes).
        // Some of which exceed the value 32767, the maximum value of 
        // a signed short). Because Java does not support an unsigned short type,
        // we need to mask in the low-order 2 bytes and obtain a 4-byte integer 
        // equivalent.
        int[] elements = new int[geoKeyDirectory.length];
        for (int i = 0; i < geoKeyDirectory.length; i++) {
            elements[i] = geoKeyDirectory[i] & 0xffff;
        }

        // Get the double field, Tag ID=34736 (0x87B0).  This field
        // will usually be present. Some TIFF products supply only the
        // European Petroleum Survey Group (EPSG) map projection ID
        // and may omit the floating-point map-projection parameters.
        // That approach is generally discouraged, but not prohibited.
        TiffField doubleParametersField = directory.findField(
            GeoTiffTagConstants.EXIF_TAG_GEO_DOUBLE_PARAMS_TAG);
        double[] doubleParameters = null;
        if (doubleParametersField != null) {
            doubleParameters = doubleParametersField.getDoubleArrayValue();
        }

        // Get the ASCII field, Tag ID=34737 (0x87B1). This field
        // is often, but not always, present.
        TiffField asciiParametersField = directory.findField(
            GeoTiffTagConstants.EXIF_TAG_GEO_ASCII_PARAMS_TAG);
        String asciiParameters = null;
        if (asciiParametersField != null) {
            asciiParameters = asciiParametersField.getStringValue();
        }

        ps.format("%nGeoKey Table%n");
        ps.println("     key     ref     len   value/pos     name");
        int k = 0;
        int n = elements.length / 4;
        for (int i = 0; i < n; i++) {
            int key = elements[k];
            int ref = elements[k + 1];
            int len = elements[k + 2];
            int vop = elements[k + 3];
            String label = "";
            if (ref == GeoTiffTagConstants.EXIF_TAG_GEO_ASCII_PARAMS_TAG.tag) {
                label = "(A)";
            } else if (ref == GeoTiffTagConstants.EXIF_TAG_GEO_DOUBLE_PARAMS_TAG.tag) {
                label = "(D)";
            }
            for (int j = 0; j < 4; j++) {
                ps.format("%8d", elements[k++]);
            }
            ps.format("   %-3s", label);

            // The first four elements in the integer array are not
            // actually a GeoKey, but rather an overall identifier
            GeoKey geoKey;
            String name;
            String interpretation;
            if (i == 0) {
                name = "~~~";
                interpretation = "~~~";
            } else {
                geoKey = keyMap.get(key);
                if (geoKey == null) {
                    name = "Unknown GeoKey";
                    interpretation = "~~~";
                } else {
                    name = geoKey.name();
                    interpretation
                        = interpretElements(
                            geoKey, ref, len, vop,
                            doubleParameters, asciiParameters);
                }
            }

            ps.format(nameFormat, name);
            ps.format("%s", interpretation);
            ps.format("%n");
        }

        // Note:  The y coordinate of the model pixel scale is backwards.
        //        GeoTIFF images are stored  from upper-left corner downward
        //        (following the conventional graphics standards). In cases
        //        where the rows in the image or rster run from north to south,
        //        one might expect that the delta-Y between rows would be
        //        a negative number.  But by the GeoTIFF standard, 
        //        the verical spacing is given as a postive   number.
        TiffField pixelScaleField = directory.findField(
            GeoTiffTagConstants.EXIF_TAG_MODEL_PIXEL_SCALE_TAG);
        double[] pixelScale;
        if (pixelScaleField == null) {
            ps.format("%nModelPixelScale is not supplied%n");
        } else {
            pixelScale = pixelScaleField.getDoubleArrayValue();
            ps.format("%nModelPixelScale%n");
            for (int i = 0; i < pixelScale.length; i++) {
                ps.format("   %15.10e", pixelScale[i]);
            }
            ps.format("%n");
        }

        TiffField modelTiepointField = directory.findField(
            GeoTiffTagConstants.EXIF_TAG_MODEL_TIEPOINT_TAG);
        if (modelTiepointField != null) {
            ps.format("%nModelTiepointTag%n");
            ps.println("           Pixel                           Model");

            double[] tiePoints = modelTiepointField.getDoubleArrayValue();
            n = tiePoints.length / 6;
            for (int i = 0; i < n; i++) {
                ps.format("   ");
                for (int j = 0; j < 3; j++) {
                    ps.format("%6.1f", tiePoints[i * 6 + j]);
                }
                ps.format("     ");
                for (int j = 3; j < 6; j++) {
                    ps.format("%13.3f", tiePoints[i * 6 + j]);
                }
                ps.format("%n");
            }
        }

        TiffField modelTransformField = directory.findField(
            GeoTiffTagConstants.EXIF_TAG_MODEL_TRANSFORMATION_TAG);
        if (modelTransformField != null) {
            ps.format("%nModelTransformationTag%n");
            double[] mtf = modelTiepointField.getDoubleArrayValue();
            if (mtf.length >= 16) {
                for (int i = 0; i < 4; i++) {
                    ps.format("   ");
                    for (int j = 0; j < 4; j++) {
                        ps.format("%13.3f", mtf[i * 4 + j]);
                    }
                    ps.format("%n");
                }
            }
        }
    }

static CoordinateTransformationCode getValueForKey(int key){
            for(CoordinateTransformationCode v: values()){
                if(v.key==key){
                    return v;
                }
            }
            return null;
        }

private static String interpretElements(
        GeoKey geoKey, int ref, int len, int valueOrPosition,
        double[] doubleParameters, String asciiParameters) {
        switch (geoKey) {
            case GTModelTypeGeoKey:
                switch (valueOrPosition) {
                    case 1:
                        return "Projected Coordinate System";
                    case 2:
                        return "Geographic Coordinate System";
                    case 3:
                        // the Geocentric coordinate system is seldom used
                        return "Geocentric Coordinate System";
                    default:
                        break;
                }
            case GTRasterTypeGeoKey:
                switch (valueOrPosition) {
                    case 1:
                        return "RasterPixelIsArea";
                    case 2:
                        return "RasterPixelIsPoint";
                    default:
                        return "User Defined";
                }
            case GeographicTypeGeoKey:
                switch (valueOrPosition) {
                    case 4269:
                        return "North American Datum 1983";
                    case 4030:
                        return "World Geodetic Survey 1984";
                    case 4326:
                        return "EPSG 4326, Geographic 2D WGS 84";
                    default:
                        break;
                }
            case GTCitationGeoKey:
                return extractAscii(asciiParameters, valueOrPosition, len);
            case GeogCitationGeoKey:
                return extractAscii(asciiParameters, valueOrPosition, len);
            case GeogAngularUnitsGeoKey:
                switch (valueOrPosition) {
                    case 9101:
                        return "Radians";
                    case 9102:
                        return "Degrees";
                    default:
                        break;
                }
            case GeogSemiMajorAxisGeoKey:
                return extractDouble(doubleParameters, valueOrPosition, len);
            case GeogInvFlatteningGeoKey:
                return extractDouble(doubleParameters, valueOrPosition, len);
            case To_WGS84_GeoKey:
                return extractDouble(doubleParameters, valueOrPosition, len);
            case ProjectedCRSGeoKey:
                // in original spec was "ProjectedCSTypeGeoKey"
                if (0 <= valueOrPosition && valueOrPosition <= 1023) {
                    return "Reserved";
                } else if (1024 <= valueOrPosition && valueOrPosition <= 32766) {
                    return "EPSG Code #" + valueOrPosition;
                } else if (valueOrPosition == 32767) {
                    return "User-Defined Projection";
                }
                break;
            case ProjectionGeoKey:
                if(valueOrPosition==32767){
                    return "User-Defined";
                }
                break;
            case ProjCoordTransGeoKey:
                CoordinateTransformationCode code = 
                    CoordinateTransformationCode.getValueForKey(valueOrPosition);
                if(code!=null){
                    return code.name();
                }
                break;
            case ProjLinearUnitsGeoKey:
                switch (valueOrPosition) {
                    case 9001:
                        return "Meter";
                    case 9002:
                        return "Foot";
                    case 9003:
                        return "Survey Foot"; // used in U.S.
                    default:
                        break;
                }
                break;
            case ProjStdParallel1GeoKey:
            case ProjStdParallel2GeoKey:
            case ProjNatOriginLongGeoKey:
            case ProjFalseEastingGeoKey:
            case ProjFalseNorthingGeoKey:
            case ProjFalseOriginLongGeoKey:
            case ProjFalseOriginLatGeoKey:
            case ProjFalseOriginEastingGeoKey:
            case ProjFalseOriginNorthingGeoKey:
            case ProjCenterLongGeoKey:
            case ProjCenterLatGeoKey:
                return String.format("%13.4f", doubleParameters[valueOrPosition]);

            default:
                break;
        }
        return "See GeoTIFF specification";
    }

private static String extractAscii(String asciiParameters, int pos, int len) {
        if (asciiParameters != null && len > 0 && pos + len <= asciiParameters.length()) {
            return asciiParameters.substring(pos, pos + len - 1);
        }
        return "~~~";
    }

private static String extractDouble(double[] doubleParameters, int pos, int len) {
        if (doubleParameters != null && doubleParameters.length >= pos + len) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < len && i < 3; i++) {
                if (i > 0) {
                    sb.append(" | ");
                }
                sb.append(Double.toString(doubleParameters[pos + i]));
            }
            if (len > 3) {
                sb.append(" | ...");
            }
            return sb.toString();
        }
        return "~~~";
    }

public String surveyFile(final File file, final boolean csv) throws ImageReadException, IOException {
        String delimiter = "  ";
        if (csv) {
            delimiter = ", ";
        }

        final StringBuilder sb = new StringBuilder();
        final Formatter fmt = new Formatter(sb);

        // Establish a TiffReader. This is just a simple constructor that
        // does not actually access the file.  So the application cannot
        // obtain the byteOrder, or other details, until the contents have
        // been read.  Then read the directories associated with the
        // file by passing in the byte source and options.
        final ByteSourceFile byteSource = new ByteSourceFile(file);
        final TiffReader tiffReader = new TiffReader(true);
        final TiffContents contents = tiffReader.readDirectories(
            byteSource,
            false, // read image data, if present
            FormatCompliance.getDefault());

        if (contents.directories.isEmpty()) {
            throw new ImageReadException("No Image File Directory (IFD) found");
        }
        final TiffDirectory directory = contents.directories.get(0);

        // Get the metadata (Tags) and write them to standard output
        final boolean hasTiffImageData = directory.hasTiffImageData();
        if (!hasTiffImageData) {
            throw new ImageReadException("No image data in file");
        }

        final int width = directory.getSingleFieldValue(TiffTagConstants.TIFF_TAG_IMAGE_WIDTH);
        final int height = directory.getSingleFieldValue(TiffTagConstants.TIFF_TAG_IMAGE_LENGTH);

        int samplesPerPixel = 1;
        final TiffField samplesPerPixelField = directory.findField(
            TiffTagConstants.TIFF_TAG_SAMPLES_PER_PIXEL);
        if (samplesPerPixelField != null) {
            samplesPerPixel = samplesPerPixelField.getIntValue();
        }
        int[] bitsPerSample = {1};
        int bitsPerPixel = samplesPerPixel;
        final TiffField bitsPerSampleField = directory.findField(
            TiffTagConstants.TIFF_TAG_BITS_PER_SAMPLE);
        if (bitsPerSampleField != null) {
            bitsPerSample = bitsPerSampleField.getIntArrayValue();
            bitsPerPixel = bitsPerSampleField.getIntValueOrArraySum();
        }
        if (samplesPerPixel != bitsPerSample.length) {
            throw new ImageReadException("Tiff: samplesPerPixel ("
                + samplesPerPixel + ")!=fBitsPerSample.length ("
                + bitsPerSample.length + ")");
        }

        int rowsPerStrip = 0;
        int tileWidth = 0;
        int tileHeight = 0;

        final boolean imageDataInStrips = directory.imageDataInStrips();
        if (imageDataInStrips) {
            final TiffField rowsPerStripField
                = directory.findField(TiffTagConstants.TIFF_TAG_ROWS_PER_STRIP);
            rowsPerStrip = Integer.MAX_VALUE;
            if (null != rowsPerStripField) {
                rowsPerStrip = rowsPerStripField.getIntValue();
            } else {
                final TiffField imageHeight = directory.findField(TiffTagConstants.TIFF_TAG_IMAGE_LENGTH);
                /*
                 * if rows per strip not present then rowsPerStrip is equal to
                 * imageLength or an infinity value;
                 */
                if (imageHeight != null) {
                    rowsPerStrip = imageHeight.getIntValue();
                }
            }
        } else {
            final TiffField tileWidthField = directory.findField(TiffTagConstants.TIFF_TAG_TILE_WIDTH);
            if (null == tileWidthField) {
                throw new ImageReadException("Can't find tile width field.");
            }
            tileWidth = tileWidthField.getIntValue();
            final TiffField tileLengthField = directory.findField(TiffTagConstants.TIFF_TAG_TILE_LENGTH);
            if (null == tileLengthField) {
                throw new ImageReadException("Can't find tile length field.");
            }
            tileHeight = tileLengthField.getIntValue();
        }

        final String compressionString = getCompressionString(directory);
        final String predictorString = getPredictorString(directory);
        final String planarConfigurationString = getPlanarConfigurationString(directory);
        final String bitsPerSampleString = getBitsPerSampleString(bitsPerSample);
        final String sampleFmtString = getSampleFormatString(directory);
        final String piString = getPhotometricInterpreterString(directory, bitsPerSample);
        final String iccString = getIccProfileString(directory);

        fmt.format("%s%4dx%-4d", delimiter, width, height);
        if (imageDataInStrips) {
            fmt.format("%sStrips%s%4dx%-4d", delimiter, delimiter, width, rowsPerStrip);
        } else {
            fmt.format("%sTiles %s%4dx%-4d", delimiter, delimiter, tileWidth, tileHeight);
        }

        fmt.format("%s%s", delimiter, planarConfigurationString);
        fmt.format("%s%-8s", delimiter, compressionString);
        fmt.format("%s%-7s", delimiter, predictorString);
        fmt.format("%s%-8s", delimiter, sampleFmtString);
        fmt.format("%s%3d", delimiter, bitsPerPixel);
        fmt.format("%s%-7s", delimiter, bitsPerSampleString);
        fmt.format("%s%-9s", delimiter, piString);
        fmt.format("%s%-7s", delimiter, iccString);

        if (csv) {
            return trimForCsv(sb);
        }
        return sb.toString();
    }

private String getCompressionString(final TiffDirectory directory) throws ImageReadException {
        final short compressionFieldValue;
        if (directory.findField(TiffTagConstants.TIFF_TAG_COMPRESSION) != null) {
            compressionFieldValue
                = directory.getFieldValue(TiffTagConstants.TIFF_TAG_COMPRESSION);
        } else {
            compressionFieldValue = TIFF_COMPRESSION_UNCOMPRESSED_1;
        }
        final int compression = 0xffff & compressionFieldValue;
        switch (compression) {
            case TIFF_COMPRESSION_UNCOMPRESSED: // None;
                return "None";
            case TIFF_COMPRESSION_CCITT_1D: // CCITT Group 3 1-Dimensional Modified
                // Huffman run-length encoding.
                return "CCITT_1D";
            case TIFF_COMPRESSION_CCITT_GROUP_3:
                return "CCITT_3";
            case TIFF_COMPRESSION_CCITT_GROUP_4:
                return "CCITT_4";
            case TIFF_COMPRESSION_LZW:
                return "LZW";
            case TIFF_COMPRESSION_PACKBITS:
                return "PACKBITS";
            case TIFF_COMPRESSION_DEFLATE_ADOBE:
            case TIFF_COMPRESSION_DEFLATE_PKZIP:
                return "Deflate";
            default:
                return "None";
        }
    }

String getPredictorString(final TiffDirectory directory) throws ImageReadException {
        int predictor = -1;

        final TiffField predictorField = directory.findField(
            TiffTagConstants.TIFF_TAG_PREDICTOR);
        if (null != predictorField) {
            predictor = predictorField.getIntValueOrArraySum();
        }

        switch (predictor) {
            case TiffTagConstants.PREDICTOR_VALUE_HORIZONTAL_DIFFERENCING:
                return "Diff";
            case TiffTagConstants.PREDICTOR_VALUE_FLOATING_POINT_DIFFERENCING:
                return "FP Diff";
            default:
                return "None";

        }
    }

String getSampleFormatString(final TiffDirectory directory) throws ImageReadException {
        final short[] sSampleFmt = directory.getFieldValue(
            TiffTagConstants.TIFF_TAG_SAMPLE_FORMAT, false);
        if (sSampleFmt == null || sSampleFmt.length == 0) {
            return "Unknown";
        }
        String heterogeneous = "";
        for (int i = 1; i < sSampleFmt.length; i++) {
            if (sSampleFmt[i] != sSampleFmt[0]) {
                heterogeneous = "*";
                break;
            }
        }
        final int test = sSampleFmt[0];
        switch (test) {
            case TiffTagConstants.SAMPLE_FORMAT_VALUE_COMPLEX_INTEGER:
                return "Comp I" + heterogeneous;
            case TiffTagConstants.SAMPLE_FORMAT_VALUE_IEEE_FLOATING_POINT:
                return "Float" + heterogeneous;
            case TiffTagConstants.SAMPLE_FORMAT_VALUE_IEEE_COMPLEX_FLOAT:
                return "Comp F" + heterogeneous;
            case TiffTagConstants.SAMPLE_FORMAT_VALUE_TWOS_COMPLEMENT_SIGNED_INTEGER:
                return "Sgn Int" + heterogeneous;
            case TiffTagConstants.SAMPLE_FORMAT_VALUE_UNSIGNED_INTEGER:
                return "Uns Int" + heterogeneous;
            default:
                return "Unknown" + heterogeneous;
        }
    }

String getBitsPerSampleString(final int[] bitsPerSample) {
        final StringBuilder s = new StringBuilder();
        for (int i = 0; i < bitsPerSample.length; i++) {
            if (i > 0) {
                s.append(".");
            }
            s.append(Integer.toString(bitsPerSample[i], 10));
        }
        return s.toString();
    }

private String getPhotometricInterpreterString(final TiffDirectory directory, final int[] bitsPerSample) throws ImageReadException {
        final int photometricInterpretation = 0xffff & directory.getFieldValue(
            TiffTagConstants.TIFF_TAG_PHOTOMETRIC_INTERPRETATION);

        switch (photometricInterpretation) {
            case 0:
                return "BiLev Inv";
            case 1:
                return "BiLevel";
            case 2:
                String a = "RGB";
                if (bitsPerSample.length == 4) {
                    final Object o = directory.getFieldValue(TiffTagConstants.TIFF_TAG_EXTRA_SAMPLES);
                    short extraSamples = 0;
                    if (o instanceof Short) {
                        extraSamples = ((Short) o);
                    }
                    if (extraSamples == 1) {
                        a = "RGB Pre-A";
                    } else {
                        a = "RGBA";
                    }
                }

                return a;
            case 3:
                return "Palette";

            case 5: // CMYK
                return "CMYK";
            case 6:
                return "YCbCr";
            case 8:
                return "CieLab";

            case 32844:
            case 32845:
                return "LogLuv";
            default:
                return "Unknown";

        }

    }

String getIccProfileString(final TiffDirectory directory) throws ImageReadException {
        final byte[] b = directory.getFieldValue(TiffEpTagConstants.EXIF_TAG_INTER_COLOR_PROFILE,
            false);
        if (b == null || b.length == 0) {
            return "N";
        }
        return "Y";
    }

String getPlanarConfigurationString(final TiffDirectory directory) throws ImageReadException {

        // Obtain the planar configuration
        final TiffField pcField = directory.findField(
            TiffTagConstants.TIFF_TAG_PLANAR_CONFIGURATION);
        final TiffPlanarConfiguration planarConfiguration
            = pcField == null
                ? TiffPlanarConfiguration.CHUNKY
                : TiffPlanarConfiguration.lenientValueOf(pcField.getIntValue());

        if (planarConfiguration == TiffPlanarConfiguration.CHUNKY) {
            return "Chunky";
        }
        return "Planar";
    }

String formatHeader(final int maxPathLen, final boolean csv) {
        // After some false starts, it turned out that the easiest
        // way to do this is just to create a regular header and then
        // search-and-replace spaces with comma as appropriate.
        int n = maxPathLen;
        if (n < 10) {
            n = 10;
        }
        final int k0 = (n - 4) / 2;
        final int k1 = (n - 4 - k0);

        final String header = String.format(
            "%" + k0 + "sPath%" + k1 + "s%s", "", "",
            "    Size     Layout  Blk_sz     P_conf  Compress  "
            + "Predict  Data_Fmt   B/P B/S      Photo     ICC_Pro");
        if (csv) {
            return reformatHeaderForCsv(header);
        }
        return header;
    }

void printLegend(final PrintStream ps) {
        ps.println("Legend:");
        ps.println("  Size      Size of image (width-by-height)");
        ps.println("  Layout    Organization of the image file (strips versus tiles)");
        ps.println("  Blk_sz    Size of internal image blocks (strips versus tiles)");
        ps.println("  P_conf    Planar configuration, Chunky (interleaved samples) versus Planar ");
        ps.println("  Compress  Compression format");
        ps.println("  Predict   Predictor");
        ps.println("  Data_Fmt  Data format");
        ps.println("  B/P       Bits per pixel");
        ps.println("  B/S       Bits per sample");
        ps.println("  Photo     Photometric Interpretation (pixel color type)");
        ps.println("  ICC_Pro   Is ICC color profile supplied");
        ps.println("");
        ps.println("  RGBA       RGB with unassociated alpha (transparency)");
        ps.println("  RGBA_Pre-A RGB with associated (premultiplied) alpha");
        ps.println("");
    }

private String reformatHeaderForCsv(final String s) {
        final StringBuilder sb = new StringBuilder(s.length());
        boolean enableComma = false;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (Character.isWhitespace(c)) {
                if (enableComma) {
                    enableComma = false;
                    sb.append(',');
                }
            } else {
                enableComma = true;
                if (Character.isUpperCase(c)) {
                    c = Character.toLowerCase(c);
                }
                sb.append(c);
            }
        }
        return sb.toString();
    }

private String trimForCsv(final StringBuilder source) {
        int n = source.length();
        final StringBuilder sb = new StringBuilder(n);
        boolean spaceEnabled = false;
        boolean spacePending = false;
        for (int i = 0; i < n; i++) {
            final char c = source.charAt(i);
            if (Character.isWhitespace(c)) {
                if (spaceEnabled) {
                    spacePending = true;
                    spaceEnabled = false;
                }
            } else {

                if (Character.isLetter(c) || Character.isDigit(c)) {
                    if (spacePending) {
                        sb.append(' ');
                        spacePending = false;
                    }
                    spaceEnabled = true;
                } else {
                    spacePending = false;
                    spaceEnabled = false;
                }
                sb.append(c);
            }
        }
        n = sb.length();
        if (n > 0 && sb.charAt(n - 1) == ' ') {
            sb.setLength(n - 1);
        }
        return sb.toString();
    }

public static void main(final String[] args) throws ImageReadException, IOException {
        if (args.length == 0) {
            // Print usage and exit
            for (final String s : USAGE) {
                System.err.println(s);
            }
            System.exit(0);
        }

        final File target = new File(args[0]);
        String outputPath = null;
        if (args.length >= 2) {
            outputPath = args[1];
        }
        final boolean optionalImageWritingEnabled
            = outputPath != null && !outputPath.isEmpty();

        final ByteSourceFile byteSource = new ByteSourceFile(target);

        // Establish a TiffReader. This is just a simple constructor that
        // does not actually access the file until one of its methods such as
        // readDirectories is called.
        final TiffReader tiffReader = new TiffReader(true);

        // Read the directories in the TIFF file.  Directories are the
        // main data element of a TIFF file. They usually include an image
        // element, but sometimes just carry metadata. This example
        // reads all the directories in the file.   Typically reading
        // the directories is not a time-consuming operation.
        final TiffContents contents = tiffReader.readDirectories(
            byteSource,
            true, // indicates that application should read image data, if present
            FormatCompliance.getDefault());

        // Read the first directory in the file.  A practical implementation
        // could use any of the directories in the file. This demo uses the
        // first one just for simplicity.
        final TiffDirectory directory = contents.directories.get(0);
        // Render the first directory in the file
        if (!directory.hasTiffFloatingPointRasterData()) {
            System.err.println("Specified directory does not contain floating-point data");
            System.exit(-1);
        }

        // Construct a TiffImageParser instance and use it to read the data.
        // If only a sub-image is desired, the params Mao can be used
        // to specify what section of the data is to be extracted.
        // See the Javadoc for readFloatingPointRasterData for more details.
        final long time0Nanos = System.nanoTime();
        final TiffImagingParameters params = new TiffImagingParameters();
        final TiffRasterData rasterData
            = directory.getRasterData(params);
        final long time1Nanos = System.nanoTime();
        System.out.println("Data read in " + ((time1Nanos - time0Nanos) / 1.0e+6) + " ms");

        // One of the test files in the Commons Imaging distribution uses
        // the value 9999 as a special "No Data" indicator.  In that case,
        // we do not want to include 9999 in the simple-statistics survey.
        final float excludedValue = Float.NaN;
        TiffRasterStatistics simpleStats;
        if ("Sample64BitFloatingPointPix451x337.tiff".equals(target.getName())) {
            simpleStats = rasterData.getSimpleStatistics(9999);
        } else {
            // just gather the standard statistics
            simpleStats = rasterData.getSimpleStatistics();
        }

        final int w = rasterData.getWidth();
        final int h = rasterData.getHeight();
        final float minValue = simpleStats.getMinValue();
        final float maxValue = simpleStats.getMaxValue();

        System.out.format("Image size %dx%d%n", w, h);
        System.out.format("Range of values in TIFF: %f %f%n", minValue, maxValue);
        System.out.format("Number of data values found %d%n",
            simpleStats.getCountOfSamples());

        if (optionalImageWritingEnabled) {
            // The easiest way to get an image is by using the
            // TiffDirectory class' getTiffImage() methods and passing in
            // an optional photometric interpreter as shown in the
            // ReadAndRenderFloatingPoint.java example,  But in this case,
            // we'll take the approach of building an image from the
            // raster data that was obtained above.
            final File output = new File(outputPath);
            System.out.println("Writing image to " + output.getPath());
            // create a new photometric interpreter based on the range
            // of values found above.
            final List<PaletteEntry> paletteList = new ArrayList<>();
            if (!Float.isNaN(excludedValue)) {
                // draw the excluded value in red.
                paletteList.add(new PaletteEntryForValue(excludedValue, Color.red));
            }
            paletteList.add(
                new PaletteEntryForRange(minValue, maxValue, Color.black, Color.white));
            // palette entries are defined for ranges   minValue <= value < maxValue.
            // Thus raster cells containing the maximum value would not be
            // color-coded unless we add an additional palette entry to
            // handle the single-value for the maximum.
            paletteList.add(new PaletteEntryForValue(maxValue, Color.white));
            final PhotometricInterpreterFloat photometricInterpreter
                = new PhotometricInterpreterFloat(paletteList);

            // Now construct an ImageBuilder to store the results
            final ImageBuilder builder = new ImageBuilder(w, h, false);
            for (int y = 0; y < h; y++) {
                for (int x = 0; x < w; x++) {
                    final float f = rasterData.getValue(x, y);
                    final int argb
                        = photometricInterpreter.mapValueToARGB(f);
                    builder.setRGB(x, y, argb);
                }
            }

            final BufferedImage bImage = builder.getBufferedImage();
            ImageIO.write(bImage, "JPEG", output);
        }
    }

