@Test
    public void testGetData() {
        final float[] result = raster.getData();
        for(int i=0; i<result.length; i++){
            assertEquals((int)result[i], data[i]);
        }
        final int []iResult = raster.getIntData();
        assertArrayEquals(data, iResult);
    }

